// Helper methods
window.DuduTaxonomy = {
  all: () => window.DUDU_STICKERS,
  getById: (id) => window.DUDU_STICKERS.find(s => s.id === id),
  getByFile: (file) => window.DUDU_STICKERS.find(s => s.file === file),
  getByMood: (mood) => window.DUDU_STICKERS.filter(s => s.mood === mood),
  getByContext: (ctx) => window.DUDU_STICKERS.filter(s => s.context === ctx),
  getRandomFromPool: (poolOrName, currentId = null) => {
    const pool = Array.isArray(poolOrName) ? poolOrName : window.DUDU_POOLS[poolOrName];
    if (!pool || !pool.length) return window.DUDU_STICKERS[0];
    const candidates = (currentId !== null && currentId !== undefined && pool.length > 1)
      ? pool.filter(id => id !== currentId)
      : pool;
    const finalPool = candidates.length > 0 ? candidates : pool;
    const pickedId = finalPool[Math.floor(Math.random() * finalPool.length)];
    return window.DuduTaxonomy.getById(pickedId) || window.DUDU_STICKERS[0];
  }
};
